function longField(label,path,value,help=''){return `<label class="code-field"><span>${esc(label)}</span><textarea aria-label="${esc(label)}" data-bind="${path}" data-kind="string" spellcheck="false">${esc(value)}</textarea>${help?`<small>${help}</small>`:''}</label>`;}
function jsonField(label,path,value,help=''){return `<label class="code-field advanced-json"><span>${esc(label)}</span><textarea aria-label="${esc(label)}" data-json="${path}" spellcheck="false">${esc(JSON.stringify(value))}</textarea>${help?`<small>${help}</small>`:''}</label>`;}
function kvEditor(label,path,value={},help=''){
  const rows=Object.entries(value||{}).map(([k,v],i)=>`<div class="structured-row key-value-row"><span class="structured-index">${i+1}</span><input type="text" class="structured-key" value="${esc(k)}" data-kv-key="${path}" data-kv-old="${esc(k)}" aria-label="${esc(label)} key ${i+1}"><input type="number" inputmode="decimal" step="any" value="${esc(v)}" data-kv-value="${path}" data-kv-name="${esc(k)}" aria-label="${esc(label)} value ${i+1}"><button type="button" class="icon-btn remove-value" data-kv-remove="${path}" data-kv-name="${esc(k)}" aria-label="Remove ${esc(k)}">×</button></div>`).join('');
  return `<div class="structured-editor"><div class="structured-heading"><div><strong>${esc(label)}</strong>${help?`<small>${esc(help)}</small>`:''}</div><button type="button" class="btn small" data-kv-add="${path}">+ Parameter</button></div><div class="structured-list">${rows||'<div class="structured-empty">No named parameters. Add one when the expression or extension needs it.</div>'}</div></div>`;
}
function complexPairEditor(label,pathI,pathQ,iValues=[],qValues=[],help=''){
  const n=Math.max(iValues?.length||0,qValues?.length||0),rows=Array.from({length:n},(_,i)=>`<div class="structured-row complex-row"><span class="structured-index">${i+1}</span><label>I<input type="number" inputmode="decimal" step="any" value="${esc(iValues?.[i]??0)}" data-pair-value="i" data-pair-a="${pathI}" data-pair-b="${pathQ}" data-pair-index="${i}"></label><label>Q<input type="number" inputmode="decimal" step="any" value="${esc(qValues?.[i]??0)}" data-pair-value="q" data-pair-a="${pathI}" data-pair-b="${pathQ}" data-pair-index="${i}"></label><button type="button" class="icon-btn remove-value" data-pair-remove data-pair-a="${pathI}" data-pair-b="${pathQ}" data-pair-index="${i}" aria-label="Remove ${esc(label)} row ${i+1}">×</button></div>`).join('');
  return `<div class="structured-editor"><div class="structured-heading"><div><strong>${esc(label)}</strong>${help?`<small>${esc(help)}</small>`:''}</div><button type="button" class="btn small" data-pair-add data-pair-a="${pathI}" data-pair-b="${pathQ}">+ Row</button></div><div class="structured-list">${rows||'<div class="structured-empty">No explicit complex values.</div>'}</div></div>`;
}
function matrix3Editor(label,path,rows=[],help=''){
  const html=(rows||[]).map((r,i)=>`<div class="structured-row matrix-row"><span class="structured-index">${i+1}</span>${['X','Y','Z'].map((axis,j)=>`<label>${axis}<input type="number" inputmode="decimal" step="any" value="${esc(r?.[j]??0)}" data-matrix-path="${path}" data-matrix-row="${i}" data-matrix-col="${j}"></label>`).join('')}<button type="button" class="icon-btn remove-value" data-matrix-remove="${path}" data-matrix-row="${i}" aria-label="Remove ${esc(label)} row ${i+1}">×</button></div>`).join('');
  return `<div class="structured-editor"><div class="structured-heading"><div><strong>${esc(label)}</strong>${help?`<small>${esc(help)}</small>`:''}</div><button type="button" class="btn small" data-matrix-add="${path}">+ Element</button></div><div class="structured-list">${html||'<div class="structured-empty">No elements defined.</div>'}</div></div>`;
}
function cellOverridesEditor(path,cells=[]){
  const shown=(cells||[]).slice(0,512),rows=shown.map((c,i)=>`<div class="cell-row"><span>${i+1}</span><input aria-label="Cell ${i+1} symbol" type="number" step="any" inputmode="numeric" value="${c.symbol}" data-cell-path="${path}" data-cell-index="${i}" data-cell-key="symbol"><input aria-label="Cell ${i+1} carrier" type="number" step="any" inputmode="numeric" value="${c.carrier}" data-cell-path="${path}" data-cell-index="${i}" data-cell-key="carrier"><select aria-label="Cell ${i+1} role" data-cell-path="${path}" data-cell-index="${i}" data-cell-key="kind">${['null','pilot','data','value'].map(v=>`<option ${c.kind===v?'selected':''}>${v}</option>`).join('')}</select><input aria-label="Cell ${i+1} I" type="number" step="any" value="${c.i??1}" data-cell-path="${path}" data-cell-index="${i}" data-cell-key="i"><input aria-label="Cell ${i+1} Q" type="number" step="any" value="${c.q??0}" data-cell-path="${path}" data-cell-index="${i}" data-cell-key="q"><select aria-label="Cell ${i+1} modulation" data-cell-path="${path}" data-cell-index="${i}" data-cell-key="modulation">${['bpsk','qpsk','8psk','16qam','64qam'].map(v=>`<option ${c.modulation===v?'selected':''}>${v}</option>`).join('')}</select><input aria-label="Cell ${i+1} gain" type="number" step="any" min="0" value="${c.gain??1}" data-cell-path="${path}" data-cell-index="${i}" data-cell-key="gain"><button type="button" class="icon-btn remove-value" data-cell-remove="${path}" data-cell-index="${i}" aria-label="Remove cell ${i+1}">×</button></div>`).join('');
  return `<div class="structured-editor cell-editor"><div class="structured-heading"><div><strong>Exact cell overrides</strong><small>Every override remains editable as fields; use the resource grid for visual painting.</small></div><button type="button" class="btn small" data-cell-add="${path}">+ Cell override</button></div><div class="cell-header"><span>#</span><span>Symbol</span><span>Carrier</span><span>Role</span><span>I</span><span>Q</span><span>Mapping</span><span>Gain</span><span></span></div><div class="cell-list">${rows||'<div class="structured-empty">No per-cell overrides. The base carrier allocation is used.</div>'}</div>${cells.length>shown.length?`<p class="hint">Showing the first ${shown.length} of ${cells.length} overrides here. All overrides still remain in the design and the grid.</p>`:''}</div>`;
}
function ofdmMappingEditor(path,d,{includeCells=true}={}){
  return numberListEditor('Active carrier indices',path+'.active_carriers',d.active_carriers,{increment:1,defaultValue:1,help:'Signed FFT indices. Leave empty to derive the allocation from guard bands.'})+
    numberListEditor('Pilot carrier indices',path+'.pilot_carriers',d.pilot_carriers,{increment:1,defaultValue:1,help:'Signed carrier indices used as known pilot references.'})+
    numberListEditor('Cyclic-prefix sequence',path+'.cp_lengths',d.cp_lengths,{min:0,increment:1,defaultValue:0,help:'Optional per-symbol CP lengths. Leave empty to use the default CP.'})+
    (includeCells?cellOverridesEditor(path+'.cells',d.cells):'');
}
function bindStructuredDesign(root,change,rerender){
  const redraw=rerender||(()=>{if(state.mode==='tx')renderTx();else if(state.mode==='radar')renderRadar();else if(state.mode==='rx')renderRx();});
  bindListEditors(root,change,redraw);
  $$('[data-kv-value]',root).forEach(el=>el.onchange=()=>{const obj=getPath(state,el.dataset.kvValue),v=Number(el.value);if(!Number.isFinite(v))return toast('Parameter values must be finite numbers');obj[el.dataset.kvName]=v;change(el.dataset.kvValue);});
  $$('[data-kv-key]',root).forEach(el=>el.onchange=()=>{const obj=getPath(state,el.dataset.kvKey),old=el.dataset.kvOld,key=el.value.trim();if(!key||key!==old&&Object.hasOwn(obj,key)){el.value=old;return toast('Parameter names must be unique');}const v=obj[old];delete obj[old];obj[key]=v;change(el.dataset.kvKey);redraw();});
  $$('[data-kv-add]',root).forEach(b=>b.onclick=()=>{const obj=getPath(state,b.dataset.kvAdd);let i=1,key='parameter1';while(Object.hasOwn(obj,key))key='parameter'+(++i);obj[key]=0;change(b.dataset.kvAdd);redraw();});
  $$('[data-kv-remove]',root).forEach(b=>b.onclick=()=>{delete getPath(state,b.dataset.kvRemove)[b.dataset.kvName];change(b.dataset.kvRemove);redraw();});
  $$('[data-pair-value]',root).forEach(el=>el.onchange=()=>{const a=getPath(state,el.dataset.pairA),b=getPath(state,el.dataset.pairB),i=+el.dataset.pairIndex,v=Number(el.value);if(!Number.isFinite(v))return toast('Enter a finite number');if(el.dataset.pairValue==='i')a[i]=v;else b[i]=v;change(el.dataset.pairValue==='i'?el.dataset.pairA:el.dataset.pairB);});
  $$('[data-pair-add]',root).forEach(b=>b.onclick=()=>{getPath(state,b.dataset.pairA).push(0);getPath(state,b.dataset.pairB).push(0);change(b.dataset.pairA);redraw();});
  $$('[data-pair-remove]',root).forEach(b=>b.onclick=()=>{const i=+b.dataset.pairIndex,a=getPath(state,b.dataset.pairA),q=getPath(state,b.dataset.pairB);if(a.length<=1)return toast('Keep at least one row');a.splice(i,1);q.splice(i,1);change(b.dataset.pairA);redraw();});
  $$('[data-matrix-path]',root).forEach(el=>el.onchange=()=>{const m=getPath(state,el.dataset.matrixPath),v=Number(el.value);if(!Number.isFinite(v))return toast('Enter a finite number');m[+el.dataset.matrixRow][+el.dataset.matrixCol]=v;change(el.dataset.matrixPath);});
  $$('[data-matrix-add]',root).forEach(b=>b.onclick=()=>{getPath(state,b.dataset.matrixAdd).push([0,0,0]);change(b.dataset.matrixAdd);redraw();});
  $$('[data-matrix-remove]',root).forEach(b=>b.onclick=()=>{const a=getPath(state,b.dataset.matrixRemove);if(a.length<=1)return toast('Keep at least one element');a.splice(+b.dataset.matrixRow,1);change(b.dataset.matrixRemove);redraw();});
  $$('[data-cell-path]',root).forEach(el=>el.onchange=()=>{const a=getPath(state,el.dataset.cellPath),c=a[+el.dataset.cellIndex],key=el.dataset.cellKey;c[key]=el.tagName==='SELECT'?el.value:Number(el.value);change(el.dataset.cellPath);});
  $$('[data-cell-add]',root).forEach(b=>b.onclick=()=>{getPath(state,b.dataset.cellAdd).push({symbol:0,carrier:0,kind:'value',i:1,q:0,modulation:'qpsk',gain:1});change(b.dataset.cellAdd);redraw();});
  $$('[data-cell-remove]',root).forEach(b=>b.onclick=()=>{getPath(state,b.dataset.cellRemove).splice(+b.dataset.cellIndex,1);change(b.dataset.cellRemove);redraw();});
}
function vectorField(label,path,value){return `<div class="vector-field"><label>${label}</label>${value.map((v,i)=>`<input aria-label="${label} ${['X','Y','Z'][i]}" data-bind="${path}.${i}" data-kind="number" type="number" step="any" value="${v}">`).join('')}</div>`;}
function bindJSON(root,change){$$('[data-json]',root).forEach(el=>el.onchange=()=>{try{const v=JSON.parse(el.value);setPath(state,el.dataset.json,v);el.setCustomValidity('');change(el.dataset.json);}catch(e){el.setCustomValidity('Enter valid JSON: '+e.message);el.reportValidity();}});}
function bindDesign(root,change,rerender){bindControls(root,change);bindJSON(root,change);bindStructuredDesign(root,change,rerender);$$('textarea',root).forEach(el=>el.onkeydown=e=>{if(e.ctrlKey&&e.key==='Enter'){el.blur();e.preventDefault();}});}
function programEditor(path){
  const p=getPath(state,path);let s=`<div class="builder-intro"><strong>Arbitrary waveform builder</strong><span>Choose a construction method; every method remains available and edits the same generated waveform. Enter exact values directly or use the steppers for convenient nudges.</span></div><section class="editor-card method-card"><h3>Construction method</h3>`+selectField('Design method',path+'.mode',p.mode,[['expression','Complex mathematical expression'],['points','Frequency / amplitude control points'],['iq','Complex I/Q sample table'],['extension','Local Python waveform']])+field('Repeat period (s)',path+'.period_s',p.period_s,{min:.000001,max:1,step:.00001})+'</section>';
  if(p.mode==='expression')s+=`<section class="editor-card"><h3>Expression</h3>${longField('Complex sample expression',path+'.expression',p.expression,'t = time within period; time = absolute simulation seconds; T = period; fs = sample rate; n = sample index; frame = capture ID; j and pi are constants. Use sin, cos, exp, where, clip, abs, angle, real, imag, conj, sqrt, tanh, sinc. Ctrl+Enter applies.')}${kvEditor('Named numeric parameters',path+'.parameters',p.parameters,'Parameters are directly available by name in the expression.')}</section>`;
  if(p.mode==='points')s+=`<div class="point-grid"><div>Time µs</div><div>Frequency Hz</div><div>Amplitude</div><div>Phase °</div><div></div>${p.points.map((k,i)=>['time_us','frequency_hz','amplitude','phase_deg'].map(key=>`<input aria-label="Point ${i+1} ${key}" data-bind="${path}.points.${i}.${key}" data-kind="number" type="number" step="any" value="${k[key]}">`).join('')+`<button class="btn" data-point-remove="${i}" data-path="${path}">×</button>`).join('')}</div><button class="btn" data-point-add="${path}">Add control point</button><p class="hint">Frequency is integrated piecewise-linearly. Amplitude and additional phase interpolate between points. Set zero amplitude for gaps; the table repeats at the specified period.</p>`;
  if(p.mode==='iq')s+=complexPairEditor('Complex I/Q sample table',path+'.samples_i',path+'.samples_q',p.samples_i,p.samples_q,'One row is one complex sample. Add/remove rows instead of editing JSON.')+field('Table sample rate (S/s)',path+'.table_rate',p.table_rate,{min:1,max:1e8})+selectField('Interpolation',path+'.table_interp',p.table_interp,['linear','hold'])+'<p class="hint">Enter any finite I/Q sequence. The table repeats independently of the period field.</p>';
  if(p.mode==='extension')s+=selectField('Waveform extension',path+'.extension',p.extension,[['','Select a local module'],...state.extensionCatalog.filter(x=>x.waveform).map(x=>x.name)])+kvEditor('Extension parameters',path+'.parameters',p.parameters,'Named numeric values passed to the extension.')+'<p class="hint">Add a Python module with waveform(context) to the project’s extensions folder and restart the server. The interface supports NumPy/SciPy algorithms beyond the expression editor. See docs/PROGRAMMING.md.</p>'; 
  return s;
}
function bindProgram(root,change,rerender){
  bindDesign(root,path=>{change(path);if(path.endsWith('.mode'))rerender();});
  $$('[data-point-add]',root).forEach(b=>b.onclick=()=>{const p=getPath(state,b.dataset.pointAdd),last=p.points.at(-1);p.points.push({...last,time_us:last.time_us+25});change(b.dataset.pointAdd);rerender();});
  $$('[data-point-remove]',root).forEach(b=>b.onclick=()=>{const p=getPath(state,b.dataset.path);if(p.points.length<3)return;p.points.splice(Number(b.dataset.pointRemove),1);change(b.dataset.path);rerender();});
}

const baseRenderTx=renderTx;
renderTx=function(){
  baseRenderTx();
  const edit=$('.parameter-editor');if(!edit)return;
  if(state.tx.waveform==='custom'){
    edit.innerHTML=programEditor('tx.program');edit.classList.add('wide-editor');
    bindProgram(edit,path=>scheduleCurrent(path),renderTx);
  } else if(state.tx.waveform==='ofdm'&&state.txPage==='modulation'){
    edit.classList.add('wide-editor');edit.innerHTML=ofdmEditor();bindOFDM(edit);refreshGrid();
  }
};
function ofdmEditor(){state.ofdmSpacing=state.tx.sample_rate/state.tx.ofdm_fft;const d=state.tx.ofdm_design,p='tx.ofdm_design';
  return `<div class="builder-intro"><strong>OFDM frame builder</strong><span>Work left-to-right: numerology → allocation → pilots → cell overrides. Every field changes the actual generated samples.</span></div>
    <div class="editor-columns ofdm-columns"><section class="editor-card"><h3>1 · Numerology</h3>${field('FFT length','tx.ofdm_fft',state.tx.ofdm_fft,{min:16,max:4096,step:16})}${field('Subcarrier spacing Hz','ofdmSpacing',state.ofdmSpacing,{min:1,max:1e7/state.tx.ofdm_fft,step:100})}${field('Frame symbols',p+'.symbols',d.symbols,{min:1,max:128,step:1})}${field('Default cyclic prefix','tx.ofdm_cp',state.tx.ofdm_cp,{min:0,max:1024,step:1})}${selectField('Payload constellation',p+'.modulation',d.modulation,['bpsk','qpsk','8psk','16qam','64qam'])}${field('WOLA overlap samples',p+'.window_samples',d.window_samples,{min:0,max:1024,step:1})}</section>
    <section class="editor-card"><h3>2 · Base allocation and pilots</h3>${field('Left guard carriers',p+'.guard_left',d.guard_left,{min:0,step:1})}${field('Right guard carriers',p+'.guard_right',d.guard_right,{min:0,step:1})}${checkField('Null DC carrier',p+'.dc_null',d.dc_null)}${field('Pilot I',p+'.pilot_i',d.pilot_i)}${field('Pilot Q',p+'.pilot_q',d.pilot_q)}${checkField('Alternate pilot polarity',p+'.pilot_alternating',d.pilot_alternating)}${selectField('Receiver equalization',p+'.equalizer',d.equalizer,[['off','Bypass'],['pilot-ls','Pilot LS + interpolation']])}</section></div>
    <section class="editor-card allocation-card"><h3>3 · Carrier and CP lists</h3>${ofdmMappingEditor(p,d,{includeCells:false})}</section>
    <section class="editor-card resource-card"><div class="grid-heading"><div><h3>4 · Resource grid</h3><p class="hint">Paint cells directly. You never need to type a resource-grid object.</p></div><span id="gridSummary"></span></div><div class="grid-tools">${selectField('Paint cell','ofdmBrush.kind',state.ofdmBrush.kind,['null','pilot','data','value'])}${field('I','ofdmBrush.i',state.ofdmBrush.i)}${field('Q','ofdmBrush.q',state.ofdmBrush.q)}${selectField('Data mapping','ofdmBrush.modulation',state.ofdmBrush.modulation,['bpsk','qpsk','8psk','16qam','64qam'])}<button id="clearGridCells" class="btn">Clear overrides</button></div><div class="grid-scroll" id="ofdmGrid"></div><p class="hint">Blue = payload, gold = pilot, purple = explicit complex value, dark = null. Rows are OFDM symbols; columns are signed subcarriers.</p>${cellOverridesEditor(p+'.cells',d.cells)}<details class="advanced-raw"><summary>Advanced raw JSON view · optional</summary>${jsonField('Exact cell overrides',p+'.cells',d.cells,'Bulk editing remains available here, but every override is editable above without JSON.')}</details><p id="gridError" class="error-text"></p></section>`;
}
function bindOFDM(root){bindDesign(root,path=>{if(path.startsWith('ofdmBrush'))return;if(path==='ofdmSpacing'){state.tx.sample_rate=state.ofdmSpacing*state.tx.ofdm_fft;const fsInput=$('[data-bind="tx.sample_rate"]');if(fsInput)fsInput.value=state.tx.sample_rate;path='tx.sample_rate';}scheduleCurrent(path);refreshGrid();},renderTx);$('#clearGridCells').onclick=()=>{state.tx.ofdm_design.cells=[];scheduleCurrent('tx.ofdm_design.cells');renderTx();};}
async function refreshGrid(){const signature=JSON.stringify(state.tx);try{const d=await jsonPost('/api/studio/ofdm',cleanTx());if(signature!==JSON.stringify(state.tx)||!$('#ofdmGrid'))return;const[rows,cols]=d.grid_shape;const limit=Math.min(cols,256);$('#gridSummary').textContent=`Δf ${fmt(d.subcarrier_spacing_hz,'Hz')} · ${rows} × ${cols}${cols>256?' · first 256 columns shown':''}`;$('#ofdmGrid').innerHTML=`<div class="resource-grid" style="grid-template-columns:44px repeat(${limit},20px)"><b>k →</b>${Array.from({length:limit},(_,i)=>`<small>${i-Math.floor(cols/2)}</small>`).join('')}${Array.from({length:rows},(_,s)=>`<b>S${s}</b>${Array.from({length:limit},(_,c)=>{const i=s*cols+c,k=c-Math.floor(cols/2);return `<button aria-label="Symbol ${s} carrier ${k}" title="S${s}, k=${k}, ${d.grid_i[i].toFixed(2)} + j${d.grid_q[i].toFixed(2)}" class="resource-cell role-${d.grid_roles[i]}" data-symbol="${s}" data-carrier="${k}"></button>`;}).join('')}`).join('')}</div>`;$$('[data-symbol]',$('#ofdmGrid')).forEach(b=>b.onclick=()=>{const symbol=Number(b.dataset.symbol),carrier=Number(b.dataset.carrier);const a=state.tx.ofdm_design.cells;a.splice(0,a.length,...a.filter(c=>c.symbol!==symbol||c.carrier!==carrier),{symbol,carrier,...state.ofdmBrush});scheduleCurrent('tx.ofdm_design.cells');refreshGrid();});$('#gridError').textContent='';}catch(e){if($('#gridError'))$('#gridError').textContent=shortError(e);}}

const baseDrawRxSync=drawRxSyncFrame;
drawRxSyncFrame=function(p){baseDrawRxSync(p);if(state.rx.modulation==='ofdm'&&state.rxData){setPlotLabel('rxLoop','Pilot channel estimate · magnitude vs carrier');linePlot($('#rxLoop'),state.rxData.telemetry.ofdm_channel_magnitude,{x:state.rxData.telemetry.ofdm_carriers});}};
const baseFollow=followTransmitter;
followTransmitter=function(){baseFollow();if(state.rxFollow){state.rx.ofdm_design=structuredClone(state.tx.ofdm_design);if(state.tx.waveform==='ofdm'&&state.lastFollowedMod!=='ofdm')state.rx.coarse_cfo=true;state.lastFollowedMod=state.tx.waveform;}};
const baseWsText=handleWsText;
handleWsText=function(m){baseWsText(m);if(m.type==='error'){let e=$('#engineError');if(!e){e=document.createElement('div');e.id='engineError';e.className='engine-error';document.body.append(e);}e.textContent=m.message+' · Display retains the last valid capture.';}if(m.type==='accepted')$('#engineError')?.remove();if(m.type==='pipeline'){state.pipelineData=m;drawPipeline();return;}if(m.type==='metrics'){state.captureID=m.capture_id??m.seq;state.simulationTime=m.simulation_time_s;if(state.tx.waveform==='ofdm'&&$('#txActual')){const cp=state.tx.ofdm_design.cp_lengths;$('#txActual').textContent=fmt(state.tx.sample_rate/(state.tx.ofdm_fft+(cp.length?cp.reduce((a,b)=>a+b,0)/cp.length:state.tx.ofdm_cp)),'Bd');}const e=$('#captureStatus');if(e)e.textContent=`FRAME ${state.captureID} · t ${fmt(state.simulationTime,'s')}`;}};
const baseSourceReadout=sourceReadout;
sourceReadout=function(){return baseSourceReadout().replace('TRANSMITTER · internal record','TRANSMITTER · live captures').replace('</b></div></div>',`</b></div><div><span>Capture</span><b id="captureStatus">FRAME ${state.captureID??0}</b></div></div>`);};
const baseWsPayload=wsPayload;
wsPayload=function(){return {...baseWsPayload(),pipeline:state.mode==='rx'&&['pipeline','monitor'].includes(state.rxPage)?state.pipeline:null,channel:state.channel};};
const baseJsonPost=jsonPost;
jsonPost=function(path,obj){if(['/api/rx/loopback','/api/measurements','/api/studio/pipeline'].includes(path))obj={...obj,capture_id:state.captureID??0};if(path==='/api/blind/generate')path+=`?capture_id=${state.captureID??0}`;return baseJsonPost(path,obj);};

const blockKinds=['gain','mixer','fir','lowpass','resample','dc','agc','expression','costas','gardner','mueller-muller','cma','extension'];
function newBlock(kind){return {name:kind.toUpperCase(),kind,enabled:true,gain_db:0,frequency_hz:0,taps_i:[1],taps_q:[],cutoff_hz:100000,taps:63,up:1,down:2,expression:'x',symbol_rate:50000,loop_gain:.05,beta:.0005,order:4,extension:'',parameters:{}};}
function pipelineEditor(path){const cfg=getPath(state,path);return `<div class="chain-tools"><select aria-label="New processing block" id="newBlockKind">${blockKinds.map(k=>`<option>${k}</option>`).join('')}</select><button class="btn" data-add-block="${path}">Add block</button><button class="btn" data-reset-chain="${path}">Reset state</button>${selectField('Scope probe',path+'.probe',cfg.probe,[[-1,'Final output'],...cfg.blocks.map((b,i)=>[i,`${i+1} · ${b.name}`])])}</div><p class="hint">Samples flow through the ordered blocks. FIR, lowpass, Costas and Python extensions carry state across live Receiver captures. Timing, resampling and CMA are capture-local. Radar processing restarts per capture.</p>${cfg.blocks.map((b,i)=>{const p=path+'.blocks.'+i;let params='';
if(b.kind==='gain')params=field('Gain dB',p+'.gain_db',b.gain_db);
if(b.kind==='mixer')params=field('Shift down Hz',p+'.frequency_hz',b.frequency_hz);
if(b.kind==='fir')params=complexPairEditor('Complex FIR taps',p+'.taps_i',p+'.taps_q',b.taps_i,b.taps_q,'Q may be zero for a real FIR.');
if(b.kind==='lowpass')params=field('Cutoff Hz',p+'.cutoff_hz',b.cutoff_hz)+field('Filter taps',p+'.taps',b.taps,{min:3,max:2047,step:2});
if(b.kind==='resample')params=field('Up',p+'.up',b.up,{min:1,max:32,step:1})+field('Down',p+'.down',b.down,{min:1,max:128,step:1});
if(b.kind==='expression')params=longField('Output expression',p+'.expression',b.expression,'x = current complex samples; t/time = absolute time; fs, n and frame are available.');
if(['costas','gardner','mueller-muller','cma'].includes(b.kind))params=field('Loop gain',p+'.loop_gain',b.loop_gain,{min:.00001,max:1,step:.001});
if(['gardner','mueller-muller'].includes(b.kind))params+=field('Output symbols/s',p+'.symbol_rate',b.symbol_rate,{min:1});
if(b.kind==='costas')params+=field('Beta',p+'.beta',b.beta,{min:.00001,max:.2,step:.0001})+selectField('Order',p+'.order',b.order,[2,4]);
if(b.kind==='cma')params+=field('Taps (≤21)',p+'.taps',b.taps,{min:3,max:21,step:2});
if(b.kind==='extension')params=selectField('Processing module',p+'.extension',b.extension,[['','Select local module'],...state.extensionCatalog.filter(x=>x.process).map(x=>x.name)])+kvEditor('Parameters',p+'.parameters',b.parameters);
return `<details class="dsp-block" open><summary><span>${i+1}. ${esc(b.name)}</span><span>${esc(b.kind)}</span></summary><div class="block-actions">${checkField('Enabled',p+'.enabled',b.enabled)}<button class="btn" data-move-block="${i}" data-direction="-1" data-path="${path}">↑</button><button class="btn" data-move-block="${i}" data-direction="1" data-path="${path}">↓</button><button class="btn" data-remove-block="${i}" data-path="${path}">Remove</button></div>${params}</details>`;}).join('')}<details class="advanced-raw"><summary>Advanced raw processing-chain JSON · optional</summary>${jsonField('Blocks',path+'.blocks',cfg.blocks,'The block cards above are the primary editor; this view is retained for bulk import/editing.')}</details>`;}
function bindPipeline(root,path,change,rerender){bindDesign(root,change);$('[data-reset-chain]',root).onclick=()=>{const cfg=getPath(state,path);cfg.reset_epoch=(cfg.reset_epoch||0)+1;change(path);};$('[data-add-block]',root).onclick=()=>{const cfg=getPath(state,path);if(cfg.blocks.length>=24)return toast('Maximum 24 blocks');const b=newBlock($('#newBlockKind').value);if(b.kind==='cma')b.taps=7;cfg.blocks.push(b);change(path);rerender();};$$('[data-remove-block]',root).forEach(b=>b.onclick=()=>{getPath(state,path).blocks.splice(Number(b.dataset.removeBlock),1);change(path);rerender();});$$('[data-move-block]',root).forEach(b=>b.onclick=()=>{const a=getPath(state,path).blocks,i=+b.dataset.moveBlock,j=i+(+b.dataset.direction);if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];change(path);rerender();});}
const baseDrawRxAnalysis=drawRxAnalysis;
drawRxAnalysis=function(){baseDrawRxAnalysis();drawOFDMReceiver();const d=state.rxData;if(state.rx.modulation==='ofdm'&&d){setPlotLabel('rxRaw','OFDM payload · equalized constellation');scatter($('#rxRaw'),d.symbols?.i,d.symbols?.q,{scale:1,ideals:idealConstellation(state.tx.ofdm_design.modulation)});setPlotLabel('rxLoop','Pilot channel estimate · magnitude vs carrier');linePlot($('#rxLoop'),d.telemetry.ofdm_channel_magnitude,{x:d.telemetry.ofdm_carriers});setPlotLabel('rxSync','OFDM payload symbols · current capture');}};
const baseRenderRx=renderRx;
renderRx=function(){
  if(state.rx.modulation==='ofdm'&&state.rxPage!=='pipeline'){renderOFDMReceiver();return;}
  if(state.rxPage!=='pipeline'){baseRenderRx();const nav=$('[data-rxpage]')?.parentElement;if(nav){const b=document.createElement('button');b.textContent='Processing chain';b.onclick=()=>{state.rxPage='pipeline';renderRx();startMode();};nav.append(b);}return;}
  const controls=group('Processing bench',sourceReadout()+'<p class="hint">Input is the live Transmitter after the Receiver channel experiment. Use built-in blocks, complex expressions or local Python extensions.</p>')+group('Channel',sliderField('SNR dB','channel.snr_db',state.channel.snr_db,{min:-10,max:60,step:1})+field('CFO Hz','channel.freq_offset_hz',state.channel.freq_offset_hz));
  $('#workspace').innerHTML=layout('Receiver · processing bench',controls,measure('Frame','pipelineFrame')+measure('Output rate','pipelineRate')+measure('RMS','pipelineRms'),subnav([['acquire','Acquisition'],['timing','Timing'],['carrier','Carrier'],['equalizer','Equalizer / channel'],['pipeline','Processing chain']],state.rxPage,'rxpage')+`<div class="studio-split"><section class="studio-editor" id="pipelineEditor">${pipelineEditor('pipeline')}</section><section class="studio-scopes">${plotPane('Input I/Q','pipelineInput')}${plotPane('Selected stage I/Q','pipelineOutput')}${plotPane('Final output spectrum','pipelineSpectrum')}<div class="result-panel" id="pipelineStages"></div></section></div>`,'with-views');
  bindView([],v=>{state.rxPage=v;renderRx();startMode();},'rxpage');bindControls($('.dock-scroll'),()=>refreshPipeline());bindPipeline($('#pipelineEditor'),'pipeline',()=>refreshPipeline(),renderRx);drawPipeline();
};
function refreshPipeline(){if(state.mode==='rx'&&state.rxPage==='pipeline')sendWsUpdate();}
function drawPipeline(){const d=state.pipelineData;if(!d||!$('#pipelineInput'))return;linePlot($('#pipelineInput'),d.input.i,{secondary:d.input.q,x:d.input.time_s,xUnit:'s'});linePlot($('#pipelineOutput'),d.output.i,{secondary:d.output.q,x:d.output.time_s,xUnit:'s'});linePlot($('#pipelineSpectrum'),d.psd_db,{x:d.freq_hz,xUnit:'Hz'});$('#pipelineFrame').textContent=d.capture_id;$('#pipelineRate').textContent=fmt(d.output_rate,'S/s');$('#pipelineRms').textContent=fmt(d.rms);$('#pipelineStages').innerHTML=`<h3>Stage measurements · capture ${d.capture_id}</h3><table class="result-table">${d.stages.map(x=>`<tr><td>${esc(x.name)} · ${esc(x.state||'')}</td><td>${fmt(x.sample_rate,'S/s')}</td><td>RMS ${fmt(x.rms)}</td></tr>`).join('')}</table>`;}

const radarViews=[['waveform','Waveform designer'],['scene','Scene'],['antenna','Antenna / array'],['processing','Processing'],['live','Live measurements']];
const radarPlotTypes=[['tx','Transmitted I/Q'],['frequency','Transmit instantaneous frequency'],['rx','Received I/Q'],['processed','Processing probe'],['spectrum','Received spectrum'],['range','Range / detection threshold'],['rd','Range–Doppler'],['angles','Measured angle response'],['pattern','Array beam pattern'],['autocorr','Transmit autocorrelation'],['scene','Scene geometry']];
function simControls(){const s=state.studio;return group('Simulation',`<div class="sim-buttons"><button id="simRun" class="btn ${s.running?'selected':''}">${s.running?'Pause':'Run'}</button><button id="simStep" class="btn">Step</button><button id="simReset" class="btn">Reset</button></div>`+field('Time advance × capture','studio.speed',s.speed,{min:.01,max:1000,step:1})+field('Sample rate S/s','studio.sample_rate',s.sample_rate,{min:2000,max:1e7,step:1000})+field('Samples / capture','studio.samples',s.samples,{min:512,max:32768,step:512})+field('RF carrier Hz','studio.carrier_hz',s.carrier_hz,{min:1e6,max:1e11,step:1e6})+'<p class="hint">Each tick synthesizes a new time-stamped receive capture and runs the processor. Pause freezes simulation time; Step processes one new capture.</p>');}
function radarMetrics(){return measure('Capture','studioFrame')+measure('Sim time','studioTime')+measure('Processing','studioCost')+measure('Peak range','studioRange')+measure('Az / El','studioAngle');}
function sourceControl(){return group('Waveform source',selectField('Construction','studio.source',state.studio.source,[['program','Custom waveform'],['legacy','Pulses / CW / FMCW / coded sequences'],['ofdm','Advanced · OFDM sensing / communications']])+`<p class="hint">The entire designed signal drives propagation and correlation. ${state.studio.source==='ofdm'?'Configure the resource grid in Transmitter → OFDM → Modulation.':''}</p>`);}
function sceneEditor(){const s=state.studio;return `<h2>Targets and motion</h2><p class="hint">Coordinates: X forward, Y lateral, Z up (metres). Velocity m/s; acceleration m/s². The radar array is at the origin. Echoes include delay, Doppler, antenna gain and range attenuation.</p><div class="target-cards">${s.targets.map((t,i)=>`<section class="target-card"><div class="block-actions"><h3>${esc(t.name)}</h3><button class="btn" data-delete-scene-target="${i}">Remove</button></div>${field('Name',`studio.targets.${i}.name`,t.name,{type:'string'})}${vectorField('Position m',`studio.targets.${i}.position`,t.position)}${vectorField('Velocity m/s',`studio.targets.${i}.velocity`,t.velocity)}${vectorField('Acceleration m/s²',`studio.targets.${i}.acceleration`,t.acceleration)}${field('RCS m²',`studio.targets.${i}.rcs_m2`,t.rcs_m2,{min:.0001,max:1e6})}${field('Additional echo gain dB',`studio.targets.${i}.gain_db`,t.gain_db,{min:-100,max:30})}${selectField('Fluctuation',`studio.targets.${i}.fluctuation`,t.fluctuation,['none','swerling1'])}</section>`).join('')}</div><button class="btn" id="addSceneTarget">Add target</button>`;}
function antennaEditor(){const a=state.studio.antenna,p='studio.antenna';return `<h2>Antenna and receive array</h2><p class="hint">Each element receives its own complex channel. Geometry is in wavelengths; the front hemisphere is X-positive. Steering and element patterns affect propagated echoes, beamformed output and measured direction.</p><div class="editor-columns"><section class="editor-card"><h3>Geometry and element pattern</h3>${selectField('Geometry',p+'.geometry',a.geometry,['linear','planar','custom'])}${a.geometry==='custom'?matrix3Editor('Element positions [x, y, z] λ',p+'.positions',a.positions,'One row per array element.'):field('Columns',p+'.columns',a.columns,{min:1,max:16,step:1})+(a.geometry==='planar'?field('Rows',p+'.rows',a.rows,{min:1,max:8,step:1}):'')+field('Spacing λ',p+'.spacing_lambda',a.spacing_lambda,{min:.05,max:4,step:.05})}${selectField('Element pattern',p+'.element',a.element,['isotropic','cosine','gaussian','table'])}${a.element==='cosine'?field('Cosine exponent',p+'.cosine_power',a.cosine_power,{min:0,max:20}):a.element==='gaussian'?field('Half-power beamwidth °',p+'.beamwidth_deg',a.beamwidth_deg,{min:1,max:360}):a.element==='table'?complexPairEditor('Pattern table · angle / level',p+'.pattern_angles',p+'.pattern_db',a.pattern_angles,a.pattern_db,'I column = azimuth angle in degrees; Q column = pattern level in dB.'):''}</section><section class="editor-card"><h3>Steering and weights</h3>${field('Steer azimuth °',p+'.steer_az_deg',a.steer_az_deg,{min:-90,max:90})}${field('Steer elevation °',p+'.steer_el_deg',a.steer_el_deg,{min:-60,max:60})}${field('Scan angular rate °/s',p+'.scan_deg_s',a.scan_deg_s,{min:-180,max:180})}${selectField('Beamformer',p+'.beamformer',a.beamformer,[['conventional','Conventional'],['mvdr','MVDR · loaded covariance']])}${complexPairEditor('Complex element weights',p+'.weights_i',p+'.weights_q',a.weights_i,a.weights_q,'Leave the table empty for uniform weighting; otherwise use one row per element.')}</section></div><p class="hint">Azimuth/elevation are estimated from the strongest measured range/Doppler cell. A linear array cannot uniquely recover elevation. Isotropic point-element and analytic patterns are system-level models; mutual coupling and 3D electromagnetic structures require external solvers.</p>`;}
function propagationControls(){const s=state.studio;return group('Propagation / receiver',selectField('Power model','studio.power_model',s.power_model,[['relative','Relative · R⁻⁴ power'],['radar-equation','Monostatic radar equation']])+(s.power_model==='relative'?sliderField('Receiver noise dB','studio.noise_db',s.noise_db,{min:-100,max:-5,step:1}):field('Transmit power W','studio.power_w',s.power_w,{min:.001,max:1e9})+field('TX gain dBi','studio.tx_gain_db',s.tx_gain_db)+field('RX gain dBi','studio.rx_gain_db',s.rx_gain_db)+field('Noise figure dB','studio.noise_figure_db',s.noise_figure_db,{min:0,max:40}))+field('System losses dB','studio.loss_db',s.loss_db,{min:0,max:100})+fold('Leakage and clutter',field('TX leakage amplitude dB','studio.leakage_db',s.leakage_db,{min:-150,max:0})+field('Diffuse noise-like clutter dB','studio.clutter_db',s.clutter_db,{min:-150,max:0})));}
function processorControls(){const s=state.studio;return group('Delay / Doppler search',field('Maximum range m','studio.max_range_m',s.max_range_m,{min:100,max:1e7})+field('Velocity half-span m/s','studio.max_velocity_mps',s.max_velocity_mps,{min:1,max:3000})+field('Doppler bins','studio.doppler_bins',s.doppler_bins,{min:9,max:81,step:2}))+fold('CA-CFAR range detector',field('Training cells / side','studio.cfar_train',s.cfar_train,{min:2,max:64,step:1})+field('Guard cells / side','studio.cfar_guard',s.cfar_guard,{min:1,max:20,step:1})+field('Nominal per-test Pfa','studio.cfar_pfa',s.cfar_pfa,{min:.000001,max:.49})+'<p class="hint">Runs on the Doppler-maximized range profile. Correlation and Doppler search change the overall false-alarm rate; nominal Pfa is not a calibrated global probability.</p>');}
renderRadar=function(){
  const s=state.studio;let controls=simControls(),body='';
  if(s.page==='waveform'){
    controls+=sourceControl();
    body=`<div class="studio-body"><section class="studio-editor" id="radarWaveEditor">${s.source==='program'?programEditor('studio.program'):s.source==='ofdm'?'<h2>Advanced: OFDM sensing</h2><p>OFDM is used in joint radar/communications research. For conventional radar designs, choose Pulses / CW / FMCW. The Transmitter OFDM resource grid, CP sequence, complex cell values and windowing drive this radar simulation.</p><button class="btn" id="editRadarOFDM">Open OFDM editor</button>':'<p>Build pulse and off-time items in the control dock. The full sequence, including its timing and agility, feeds the simulation.</p>'}</section><div class="studio-two">${plotPane('Transmitted I/Q · current capture','studioTx')}${plotPane('Received I/Q · current capture','studioRx')}</div></div>`;
  } else if(s.page==='scene'){
    controls+=propagationControls();body=`<div class="studio-body"><section class="studio-editor" id="sceneEditor">${sceneEditor()}</section><div class="studio-two">${plotPane('Scene geometry · live X/Y coordinates','studioScene')}${plotPane('Measured range · current capture','studioRangePlot')}</div></div>`;
  } else if(s.page==='antenna'){
    controls+=group('Observation','<p class="hint">The gold pattern is the current transmit array response. The angle heatmap comes from received array samples. Set scan rate to sweep the beam through the scene.</p>');body=`<div class="studio-body"><section class="studio-editor" id="antennaEditor">${antennaEditor()}</section><div class="studio-two">${plotPane('Array response · current steering','studioPattern')}${plotPane('Measured azimuth / elevation','studioAngles')}</div></div>`;
  } else if(s.page==='processing'){
    controls+=processorControls();body=`<div class="studio-split"><section class="studio-editor" id="radarPipelineEditor">${pipelineEditor('studio.pipeline')}</section><section class="studio-scopes">${plotPane('Processing probe I/Q','studioProcessed')}${plotPane('Processed receive spectrum','studioSpectrum')}<div class="result-panel" id="radarStageStats"></div></section></div>`;
  } else {
    controls+=processorControls()+fold('Scope assignment',['A','B','C','D'].map(k=>selectField('Panel '+k,'studio.plot'+k,s['plot'+k],radarPlotTypes)).join(''));
    body=`<div class="view-plots quad">${['A','B','C','D'].map(k=>plotPane(radarPlotTypes.find(x=>x[0]===s['plot'+k])?.[1]||'',`studioPlot${k}`)).join('')}</div><details class="measurement-results"><summary>Detections, coordinates, simulation truth and model notes</summary><div id="radarResults"></div></details>`;
  }
  const nav=subnav(radarViews,s.page,'studiopage'),error=`<div id="studioError" class="studio-error" ${s.error?'':'hidden'}>${esc(s.error)}</div>`;
  if(s.page==='waveform'&&s.source==='legacy'){
    renderRadarOriginal();renderSegmentEditor();$('.measurebar').innerHTML=radarMetrics();const gridEl=$('.plot-grid');gridEl.className='plot-grid with-views';gridEl.innerHTML=nav+error+body;const scroll=$('.dock-scroll');scroll.insertAdjacentHTML('afterbegin',`<div id="studioLegacyControls">${controls}</div>`);bindDesign($('#studioLegacyControls'),studioChanged);
  }else{
    $('#workspace').innerHTML=layout('Radar · waveform simulation',controls,radarMetrics(),nav+error+body,'with-views');bindDesign($('.dock-scroll'),studioChanged);
  }
  bindView([],v=>{s.page=v;renderRadar();},'studiopage');
  $('#simRun').onclick=()=>{s.running=!s.running;$('#simRun').textContent=s.running?'Pause':'Run';if(s.running)radarTick();};
  $('#simStep').onclick=()=>{s.running=false;$('#simRun').textContent='Run';radarTick(true);};
  $('#simReset').onclick=()=>{s.capture_id=0;s.time_s=0;s.revision++;radarTick(true);};
  if(s.page==='waveform'&&s.source==='program')bindProgram($('#radarWaveEditor'),studioChanged,renderRadar);
  if($('#editRadarOFDM'))$('#editRadarOFDM').onclick=()=>{state.txFamily='multicarrier';state.tx.waveform='ofdm';state.txPage='modulation';switchMode('tx');};
  if(s.page==='scene'){
    bindDesign($('#sceneEditor'),studioChanged);$('#addSceneTarget').onclick=()=>{if(s.targets.length>=12)return;s.targets.push({name:'Target '+(s.targets.length+1),position:[4500,-1000,500],velocity:[20,10,0],acceleration:[0,0,0],rcs_m2:1,gain_db:-6,fluctuation:'none'});studioChanged();renderRadar();};$$('[data-delete-scene-target]').forEach(b=>b.onclick=()=>{s.targets.splice(+b.dataset.deleteSceneTarget,1);studioChanged();renderRadar();});
  }
  if(s.page==='antenna')bindDesign($('#antennaEditor'),path=>{studioChanged(path);if(['geometry','element'].some(x=>path.endsWith('.'+x)))renderRadar();});
  if(s.page==='processing')bindPipeline($('#radarPipelineEditor'),'studio.pipeline',studioChanged,renderRadar);
  drawStudioRadar();
};
function studioChanged(path=''){
  state.studio.revision++;state.studio.error='';
  if(['studio.source','studio.power_model'].includes(path)||path.startsWith('studio.plot'))renderRadar();
  clearTimeout(state.studio.debounce);state.studio.debounce=setTimeout(()=>radarTick(true,false),180);
}
function radarRequest(){const s=state.studio;return {source:s.source,legacy:state.radar,program:s.program,ofdm:{...cleanTx(),waveform:'ofdm'},sample_rate:s.sample_rate,samples:s.samples,capture_id:s.capture_id,time_s:s.time_s,carrier_hz:s.carrier_hz,targets:s.targets,antenna:s.antenna,pipeline:s.pipeline,power_model:s.power_model,power_w:s.power_w,tx_gain_db:s.tx_gain_db,rx_gain_db:s.rx_gain_db,noise_figure_db:s.noise_figure_db,noise_db:s.noise_db,loss_db:s.loss_db,clutter_db:s.clutter_db,leakage_db:s.leakage_db,max_range_m:s.max_range_m,max_velocity_mps:s.max_velocity_mps,doppler_bins:s.doppler_bins,cfar_guard:s.cfar_guard,cfar_train:s.cfar_train,cfar_pfa:s.cfar_pfa,seed:s.seed,processing:s.processing};}
async function radarTick(force=false,advance=true){
  const s=state.studio;if(!force&&performance.now()-(s.lastTick||0)<1000/(s.fps||60))return;if(state.mode!=='radar'||document.hidden||s.busy||(!s.running&&!force))return;s.busy=true;s.lastTick=performance.now();const revision=s.revision,started=performance.now();
  try{const d=await baseJsonPost('/api/studio/radar',radarRequest());if(revision!==s.revision)return;s.data=d;s.compute_ms=performance.now()-started;s.actual_fps=s.lastCompleted?1000/(performance.now()-s.lastCompleted):0;s.lastCompleted=performance.now();s.error='';if(advance){s.capture_id++;s.time_s+=s.samples/s.sample_rate*s.speed;}drawStudioRadar();setStatus(`radar frame ${d.capture_id} · simulated ${fmt(d.time_s,'s')}`);}catch(e){s.error=shortError(e);if($('#studioError')){$('#studioError').hidden=false;$('#studioError').textContent=s.error+' · Last successful capture retained.';}setStatus('radar design validation error');}finally{s.busy=false;}
}
function scenePlot(canvas,d){if(!canvas)return;const z=canvasCtx(canvas);if(!z)return;const[c,w,h]=z;grid(c,w,h);const span=Math.max(state.studio.max_range_m,...d.truth.map(t=>Math.max(Math.abs(t.position[0]),Math.abs(t.position[1]))*1.15));const x=v=>35+v/span*(w-60),y=v=>h/2-v/span*(h/2-30);c.font='11px Consolas';c.fillStyle='#aab9c3';c.fillText('X forward (m) →',35,h-8);c.fillText('Y lateral',4,15);c.fillStyle='#cdd9e0';c.fillRect(x(0)-4,y(0)-4,8,8);for(const t of d.truth){c.fillStyle='#77b7d8';c.beginPath();c.arc(x(t.position[0]),y(t.position[1]),5,0,7);c.fill();c.fillText(t.name,x(t.position[0])+8,y(t.position[1])-6);}if(d.estimated_position){c.strokeStyle='#e7b954';const p=d.estimated_position;c.strokeRect(x(p[0])-7,y(p[1])-7,14,14);}c.fillStyle='#aab9c3';c.fillText('Blue: truth · gold: strongest-cell estimate',35,28);}
function drawRadarScope(canvas,kind,d){if(!canvas)return;
 const iq=(a)=>linePlot(canvas,a.i,{secondary:a.q,x:a.time_s,xUnit:'s'});
 if(kind==='tx')iq(d.tx);else if(kind==='rx')iq(d.rx);else if(kind==='processed')iq(d.processed);
 else if(kind==='frequency')linePlot(canvas,d.tx_frequency_hz,{x:d.tx_time_s,xUnit:'s'});
 else if(kind==='spectrum')linePlot(canvas,d.psd_db,{x:d.freq_hz,xUnit:'Hz'});
 else if(kind==='range')linePlot(canvas,d.range_db,{secondary:d.threshold_db,x:d.range_m,xUnit:'m'});
 else if(kind==='rd')heatmap(canvas,d.rd_db,d.rd_shape,{x:d.range_m,y:d.velocity_mps,xUnit:'m',yUnit:'m/s'});
 else if(kind==='angles')heatmap(canvas,d.angle_db,d.angle_shape,{x:d.angle_az,y:d.angle_el,xUnit:'°',yUnit:'°'});
 else if(kind==='pattern')linePlot(canvas,d.pattern_db,{x:d.angle_az,xUnit:'°',min:-60,max:3});
 else if(kind==='autocorr')linePlot(canvas,d.autocorr_db,{x:d.autocorr_delay_s,xUnit:'s',min:-70,max:1});
 else if(kind==='scene')scenePlot(canvas,d);
 canvas.dataset.capture=String(d.capture_id);const label=canvas.closest('.plot-pane')?.querySelector('.plot-value');if(label)label.textContent=`frame ${d.capture_id} · ${fmt(d.time_s,'s')}`;
}
function drawStudioRadar(){const s=state.studio,d=s.data;if(!d||state.mode!=='radar')return;
 for(const[id,value]of [['studioFrame',d.capture_id],['studioTime',fmt(d.time_s,'s')],['studioCost',fmt(s.compute_ms,'ms')],['studioRange',fmt(d.peak_range_m,'m')],['studioAngle',`${fmt(d.azimuth_deg,'°')} / ${fmt(d.elevation_deg,'°')}`]])if($('#'+id))$('#'+id).textContent=value;
 if($('#studioError')){$('#studioError').hidden=!s.error;$('#studioError').textContent=s.error;}
 for(const[id,kind]of [['studioTx','tx'],['studioRx','rx'],['studioScene','scene'],['studioRangePlot','range'],['studioPattern','pattern'],['studioAngles','angles'],['studioProcessed','processed'],['studioSpectrum','spectrum']])drawRadarScope($('#'+id),kind,d);
 for(const k of ['A','B','C','D'])drawRadarScope($('#studioPlot'+k),s['plot'+k],d);
 if($('#radarStageStats'))$('#radarStageStats').innerHTML=`<h3>Stage measurements</h3><table class="result-table">${d.stages.map(x=>`<tr><td>${esc(x.name)} · ${esc(x.state||'')}</td><td>${fmt(x.sample_rate,'S/s')}</td><td>RMS ${fmt(x.rms)}</td></tr>`).join('')}</table><p class="hint">The final processed output feeds the delay/Doppler correlator. The probe selects only the displayed intermediate stage.</p>`;
 if($('#radarResults'))$('#radarResults').innerHTML=`<div class="editor-columns"><div><h3>Measured strongest cell</h3><p>Range ${fmt(d.peak_range_m,'m')} · radial velocity ${fmt(d.peak_velocity_mps,'m/s')}</p><p>Azimuth ${fmt(d.azimuth_deg,'°')} · elevation ${fmt(d.elevation_deg,'°')}</p><p>Estimated XYZ ${d.estimated_position?.map(v=>fmt(v,'m')).join(' / ')||'Requires observable azimuth and elevation'}</p><h4>Range detections</h4>${d.detections.map(x=>`<div>${fmt(x.range_m,'m')} · ${fmt(x.power_db,'dB')}</div>`).join('')||'<p>No threshold crossings.</p>'}</div><div><h3>Simulation truth</h3>${d.truth.map(t=>`<p>${esc(t.name)}: ${t.position.map(v=>fmt(v,'m')).join(' / ')}<br>R ${fmt(t.range_m,'m')}, v ${fmt(t.velocity_mps,'m/s')}</p>`).join('')}${d.warnings.map(x=>`<p class="error-text">${esc(x)}</p>`).join('')}<p class="hint">${esc(d.method)}</p></div></div>`;
}
const baseStartMode=startMode;
startMode=function(){
  if(state.mode==='radar'){stopModeTimers();closeWs();setSourceStatus('Radar simulation',state.studio.sample_rate);radarTick(true,false);state.timers.poll=setInterval(()=>radarTick(),16);return;}
  if(state.mode==='rx'&&state.rxPage==='pipeline'){stopModeTimers();openWs();refreshPipeline();return;}
  baseStartMode();if(state.wsReady)sendWsUpdate();
};
const baseSchedule=scheduleCurrent;
scheduleCurrent=function(path=''){if(path.startsWith('radar.')){state.radarRevision++;studioChanged(path);return;}baseSchedule(path);};
window.addEventListener('resize',()=>{if(state.mode==='radar')drawStudioRadar();if(state.mode==='rx'&&state.rxPage==='pipeline')drawPipeline();});
function renderOFDMReceiver(){
  const controls=group('Demodulation · OFDM tuning',sourceReadout()+checkField('Follow transmitter format','rxFollow',state.rxFollow)+checkField('CP frequency acquisition','rx.coarse_cfo',state.rx.coarse_cfo)+'<p class="hint">Known frame boundaries and resource map. CP correlation estimates fractional CFO within ± half a subcarrier spacing. Pilot LS corrects per-symbol channel gain and phase.</p>')+group('Channel experiment',sliderField('SNR dB','channel.snr_db',state.channel.snr_db,{min:-10,max:60,step:1})+field('CFO Hz','channel.freq_offset_hz',state.channel.freq_offset_hz)+field('Phase °','channel.phase_offset_deg',state.channel.phase_offset_deg)+field('Echo gain','channel.echo_gain',state.channel.echo_gain,{min:0,max:.9,step:.01}))+group('Resource mapping',`<p class="hint">${state.rxFollow?'Following the Transmitter resource grid.':'Receiver mapping can be edited below.'}</p>`+(state.rxFollow?'':ofdmMappingEditor('rx.ofdm_design',state.rx.ofdm_design)+field('FFT','rx.ofdm_fft',state.rx.ofdm_fft,{min:16,max:4096,step:16})+field('Default CP','rx.ofdm_cp',state.rx.ofdm_cp,{min:0,step:1})));
  const views=subnav([['ofdm','OFDM receiver'],['pipeline','Processing chain']], 'ofdm','rxpage');
  const plots=plotPane('Equalized payload constellation','ofdmConst')+plotPane('Pilot LS channel magnitude','ofdmChannel')+plotPane('Payload EVM vs symbol','ofdmEvm')+`<div class="plot-pane result-cell"><div class="plot-label">Decoded payload · current capture</div><div class="result-panel"><p id="ofdmStatus" class="hint"></p>${subnav([['text','Text'],['hex','Hex'],['bits','Bits']],state.rxOutput,'rxoutput')}<pre class="decoded" id="ofdmText"></pre></div></div>`;
  $('#workspace').innerHTML=layout('Receiver · demodulation',controls,measure('Capture','ofdmFrame')+measure('EVM RMS','rxEvm')+measure('MER','rxMer')+measure('CP CFO','ofdmCFO'),views+`<div class="view-plots quad">${plots}</div>`,'with-views');
  bindDesign($('.dock-scroll'),path=>{if(path==='rxFollow'){followTransmitter();renderRx();}scheduleCurrent(path);});bindView([],v=>{state.rxPage=v;renderRx();startMode();},'rxpage');bindView([],v=>{state.rxOutput=v;drawOFDMReceiver();},'rxoutput');drawOFDMReceiver();
}
function drawOFDMReceiver(){const d=state.rxData;if(!d||!$('#ofdmConst'))return;scatter($('#ofdmConst'),d.symbols?.i,d.symbols?.q,{scale:1,ideals:idealConstellation(state.rx.ofdm_design.modulation)});linePlot($('#ofdmChannel'),d.telemetry.ofdm_channel_magnitude,{x:d.telemetry.ofdm_carriers});linePlot($('#ofdmEvm'),d.telemetry.evm_time_percent,{min:0});$('#ofdmFrame').textContent=d.tx_metadata.capture_id;$('#ofdmCFO').textContent=fmt(d.telemetry.ofdm_cfo_hz,'Hz');$('#rxEvm').textContent=fmt(d.metrics.evm_rms_percent,'%');$('#rxMer').textContent=fmt(d.metrics.mer_db,'dB');$('#ofdmStatus').textContent=`Capture ${d.tx_metadata.capture_id} · ${d.telemetry.ofdm_symbols||0} complete OFDM symbols · mixed cell mappings follow the resource grid.`;$('#ofdmText').textContent=state.rxOutput==='hex'?d.hex:state.rxOutput==='bits'?(d.bits||[]).join('').match(/.{1,64}/g)?.join('\n'):(d.text||'');$$('[data-rxoutput]').forEach(b=>b.classList.toggle('active',b.dataset.rxoutput===state.rxOutput));}
